create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin insert into public.profiles(id,email,display_name,role,is_admin,subscription_tier) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'display_name',new.raw_user_meta_data->>'name',split_part(new.email,'@',1)),case when lower(new.email)='matthagersr@gmail.com' then 'admin'::account_role else 'customer'::account_role end,lower(new.email)='matthagersr@gmail.com',case when lower(new.email)='matthagersr@gmail.com' then 'enterprise'::subscription_tier else 'free'::subscription_tier end) on conflict(id) do update set email=excluded.email,display_name=coalesce(nullif(public.profiles.display_name,''),excluded.display_name),role=case when lower(excluded.email)='matthagersr@gmail.com' then 'admin'::account_role else public.profiles.role end,is_admin=public.profiles.is_admin or lower(excluded.email)='matthagersr@gmail.com',subscription_tier=case when lower(excluded.email)='matthagersr@gmail.com' then 'enterprise'::subscription_tier else public.profiles.subscription_tier end; return new; end; $$; drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
